style.css:
@-moz-document domain("amazon.com") {
/* General Body Setup */
    * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }

    body {
        font-family: 'Arial', sans-serif;
        background-color: #f7f7f7; /* Changing the background color */
        color: #333;
        line-height: 1.6;
    }

    /* Header - Top navigation bar */
    #navbar {
        background-color: #0070f3; /* New header background color */
        color: white;
        padding: 10px 0;
    }

    #navbar a {
        color: white;
        text-decoration: none;
        padding: 12px 20px;
        margin: 0 15px;
        font-weight: bold;
        transition: background-color 0.3s ease;
    }

    #navbar a:hover {
        background-color: #0056b3; /* Hover effect for links */
        border-radius: 5px;
    }

    /* Main search button styling */
    .nav-search-submit input {
        background-color: #ff9900; /* New color for the search button */
        color: white;
        padding: 12px 25px;
        font-size: 16px;
        border: none;
        border-radius: 5px;
        cursor: pointer;
        transition: background-color 0.3s ease;
    }

    .nav-search-submit input:hover {
        background-color: #e68a00; /* Hover effect for search button */
    }

    /* Header and product titles */
    h1, h2, h3 {
        color: #222;
        margin-bottom: 20px;
    }

    /* Sidebar navigation customization */
    #side-nav {
        background-color: #222;
        padding: 20px;
        color: white;
    }

    #side-nav a {
        color: #fff;
        text-decoration: none;
        padding: 8px 12px;
        display: block;
        margin-bottom: 10px;
        border-radius: 5px;
        transition: background-color 0.3s ease;
    }

    #side-nav a:hover {
        background-color: #0056b3; /* Hover effect for sidebar links */
    }

    /* Product listings and images */
    .s-main-slot .s-result-item {
        background-color: white;
        border: 1px solid #ddd;
        padding: 15px;
        border-radius: 10px;
        margin-bottom: 20px;
        transition: transform 0.3s ease, box-shadow 0.3s ease;
    }

    .s-main-slot .s-result-item:hover {
        transform: translateY(-5px);
        box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1); /* Hover effect for product items */
    }

    .s-main-slot img {
        max-width: 100%;
        height: auto;
        border-radius: 8px;
    }

    /* Button styling for actions like "Add to Cart" */
    .a-button {
        background-color: #ff9900; /* New color for buttons */
        color: white;
        padding: 12px 20px;
        font-size: 16px;
        border-radius: 5px;
        transition: background-color 0.3s ease;
    }

    .a-button:hover {
        background-color: #e68a00; /* Hover effect for buttons */
    }

    /* Footer section customization */
    #navFooter {
        background-color: #111;
        color: white;
        padding: 20px 0;
    }

    #navFooter a {
        color: #ccc;
        text-decoration: none;
        margin: 10px;
    }

    #navFooter a:hover {
        color: #ff9900; /* Hover effect for footer links */
    }

    /* Text effect for product names */
    .a-text-normal {
        color: #0070f3;
        font-weight: bold;
        transition: color 0.3s ease;
    }

    .a-text-normal:hover {
        color: #0056b3; /* Hover effect for text links */
    }

    /* Sidebar widgets styling */
    .s-widget {
        background-color: #f4f4f4;
        border-radius: 8px;
        padding: 15px;
    }

    .s-widget h2 {
        color: #0070f3;
        font-size: 22px;
        margin-bottom: 15px;
    }

    /* Responsive Design for different screen sizes */
    @media (max-width: 768px) {
        #navbar {
            padding: 10px;
        }

        .nav-search-submit input {
            padding: 10px;
            font-size: 14px;
        }

        .s-main-slot .s-result-item {
            padding: 10px;
            margin-bottom: 15px;
        }

        .a-button {
            padding: 10px 15px;
            font-size: 14px;
        }

        #side-nav {
            padding: 15px;
        }

        #navFooter {
            padding: 15px 0;
        }
    }

    @media (max-width: 480px) {
        /* Mobile-specific styling */
        #navbar {
            padding: 10px;
            text-align: center;
        }

        .s-main-slot .s-result-item {
            padding: 10px;
        }
    }
}
